let demoCart=[],demoMarketFilter='Все',demoMarketSearch='',demoOffers=[];
let marketAccountKey=null;
function marketStorageKey(kind){return 'farm-demo-'+kind+':'+(account?.id||'guest')}
function readMarketArray(kind){try{const value=JSON.parse(localStorage.getItem(marketStorageKey(kind))||'[]');return Array.isArray(value)?value:[]}catch{return []}}
function syncMarketAccount(){const key=account?.id||'guest';if(key===marketAccountKey)return;marketAccountKey=key;demoCart=readMarketArray('cart').filter(x=>x&&demoCatalog.some(p=>p.id===x.id)&&Number.isInteger(x.qty)&&x.qty>0&&x.qty<=99);demoOffers=readMarketArray('offers').filter(x=>x&&typeof x.name==='string'&&Number.isFinite(x.price));}
function saveDemoMarket(){localStorage.setItem(marketStorageKey('cart'),JSON.stringify(demoCart));localStorage.setItem(marketStorageKey('offers'),JSON.stringify(demoOffers))}
function changeDemoQuantity(id,delta){syncMarketAccount();const row=demoCart.find(x=>x.id===id);if(!row)return;row.qty=Math.min(99,row.qty+delta);demoCart=demoCart.filter(x=>x.qty>0);saveDemoMarket();render()}
async function demoOrderHistory(){syncMarketAccount();let orders;try{orders=account?(await api('market-orders')).orders:readMarketArray('market-orders')}catch(e){toast(e.message);return}formAsync('Мои пробные корзины',orders.length?orders.slice().reverse().map(o=>`<article class="panel"><b>🧺 ${esc(new Date(o.created_at||o.date).toLocaleDateString('ru-RU'))}</b><p>${esc(o.status)}</p><p>${esc(o.report||'')}</p>${o.stage==='requested'?`<button type="button" class="btn light" onclick="marketStage('${o.id}','cancelled')">Отменить и вернуть демосредства</button>`:''}${account?.role==='admin'&&['requested','packing'].includes(o.stage)?`<button type="button" class="btn" onclick="marketStage('${o.id}','${o.stage==='requested'?'packing':'received'}')">${o.stage==='requested'?'Комплектовать':'Подтвердить получение'}</button>`:''}${(o.items||[]).map(i=>`<p>${esc(i.name)} × ${Number(i.qty)||0}</p>`).join('')}</article>`).join(''):'<p>Здесь появятся ваши пробные заказы.</p>',async()=>{})}
function searchDemoMarket(input){const start=input.selectionStart;demoMarketSearch=input.value;render();const next=document.querySelector('[data-market-search]');next?.focus();next?.setSelectionRange(start,start)}
function addDemoItem(id){syncMarketAccount();const p=demoCatalog.find(p=>p.id===id);if(!p)return;const old=demoCart.find(x=>x.id===id);if(old)old.qty=Math.min(99,old.qty+1);else demoCart.push({id,qty:1});saveDemoMarket();toast('Добавлено в демо-корзину');render()}
function demoMarketPage(){syncMarketAccount();const items=demoCatalog.filter(p=>(demoMarketFilter==='Все'||p.category===demoMarketFilter)&&p.name.toLowerCase().includes(demoMarketSearch.toLowerCase()));return heading('Маркет','Всё для грядки и корзины домой.')+`<p class="neighbor-demo">Демонстрационный каталог · 150 позиций. Заказы имитируются. В аккаунте используется демобаланс; реальные деньги, товары и доставка не задействованы.</p><div class="actions"><button class="btn" onclick="demoCheckout()">Корзина · ${demoCart.reduce((s,x)=>s+x.qty,0)}</button><button class="btn light" onclick="demoSell()">Продать / сдать в аренду</button><button class="btn light" onclick="location.hash='lifecycle'">Мой настоящий урожай</button></div><button class="btn light" onclick="demoOrderHistory()">🧺 Мои пробные заказы</button><label>Поиск<input data-market-search value="${esc(demoMarketSearch)}" placeholder="Томаты, полив, бортик…" oninput="searchDemoMarket(this)"></label><div class="actions">${['Все',...marketGroups.map(x=>x[0])].map(c=>`<button class="btn ${c===demoMarketFilter?'':'light'}" onclick="demoMarketFilter='${c}';render()">${c}</button>`).join('')}</div>${demoCart.length?`<section class="panel"><h2>🧺 Собираем корзину</h2>${demoCart.map(x=>`<div class="actions"><span>${esc(demoCatalog.find(p=>p.id===x.id).name)}</span><button class="btn light" aria-label="Уменьшить количество" onclick="changeDemoQuantity('${x.id}',-1)">−</button><b>${x.qty}</b><button class="btn light" aria-label="Увеличить количество" onclick="changeDemoQuantity('${x.id}',1)">+</button></div>`).join('')}</section>`:''}<div class="grid">${items.map(p=>`<article class="panel"><span style="font-size:38px">${({'Семена':'🌱','Рассада':'🪴','Овощи':'🥕','Полив':'💧','Обустройство':'🪵'})[p.category]}</span><small> ДЕМО · ${p.category}</small><h3>${p.name}</h3><p>${p.price} демо-₽ / ${p.rent?'месяц аренды':p.unit}</p><p>${p.category==='Овощи'?'Пример свежего урожая. Срок и вес подтверждаются при реальном заказе.':'Состав и совместимость уточняются перед реальной установкой.'}</p><button class="btn" onclick="addDemoItem('${p.id}')">${p.rent?'Арендовать':'В корзину'}</button></article>`).join('')}</div>${demoOffers.length?'<section class="panel"><h2>Мои демо-предложения</h2>'+demoOffers.map(x=>`<p>${esc(x.name)} · ${esc(x.mode)} · ${x.price} демо-₽</p>`).join('')+'</section>':''}`}
function demoCheckout(){syncMarketAccount();const orderKey=crypto.randomUUID();if(!demoCart.length){toast('Сначала добавьте товары');return}const rows=demoCart.map(x=>({...demoCatalog.find(p=>p.id===x.id),qty:x.qty})).filter(x=>x.name);formAsync('Демонстрационный заказ',`${rows.map(x=>`<p>${esc(x.name)} × ${x.qty} · ${x.price*x.qty} демо-₽</p>`).join('')}<h3>Итого: ${rows.reduce((s,x)=>s+x.price*x.qty,0)} демо-₽</h3><label>Получение<select name="delivery"><option>Доставка домой — имитация</option><option>Самовывоз — имитация</option><option>На грядку — имитация</option></select></label><label>Грядка для получения<select name="plot"><option value="">Выберите при доставке на грядку</option>${account?plotOptions():''}</select></label><p>${account?'Сумма спишется с демобаланса. Заказ сохранится в вашем аккаунте.':'Гостевой заказ сохранится только в этом браузере.'} Товары и доставка демонстрационные; реальные деньги не используются.</p><button class="btn">Оформить демо-заказ</button>`,async f=>{if(account){await api('market-checkout',{key:orderKey,delivery:f.get('delivery'),plot:Number(f.get('plot'))||null,items:rows.map(x=>({id:x.id,qty:x.qty}))});walletData=null;demoCart=[];saveDemoMarket();toast('Пробная корзина сохранена в аккаунте');return}const orders=readMarketArray('market-orders');orders.push({date:new Date().toISOString(),delivery:f.get('delivery'),items:rows,status:'Демо: ожидает согласования'});localStorage.setItem(marketStorageKey('market-orders'),JSON.stringify(orders));demoCart=[];saveDemoMarket();toast('Демо-заказ сохранён в этом браузере')})}
function demoSell(){formAsync('Разместить демо-предложение','<label>Название<input name="name" required maxlength="80"></label><label>Тип<select name="mode"><option>Продажа</option><option>Аренда в месяц</option></select></label><label>Цена, демо-₽<input name="price" type="number" min="1" max="1000000" required></label><p>Объявление видно только в этом браузере. Реальный урожай продаётся через склад и приёмку.</p><button class="btn">Разместить демо-предложение</button>',async f=>{demoOffers.push({name:f.get('name'),mode:f.get('mode'),price:Number(f.get('price'))});saveDemoMarket()})}
const beforeDemoMarketRender=render;render=function(){beforeDemoMarketRender();if(location.hash==='#market')$('#app').innerHTML=demoMarketPage();document.querySelectorAll('.neighbor-bed').forEach(b=>{const text=b.querySelector('small');if(text&&b.querySelector('span:not(.neighbor-soil)'))text.style.fontWeight='700'})};render();
